import { FOREVER, poller, sleep } from "@adviser/cement";
it("polls until success", async () => {
    const seq = vi
        .fn()
        .mockResolvedValueOnce({ state: "waiting" })
        .mockResolvedValueOnce({ state: "waiting" })
        .mockResolvedValueOnce({ state: "waiting" })
        .mockResolvedValueOnce({ state: "waiting" })
        .mockImplementationOnce(async () => {
        await sleep(50);
        return {
            state: "success",
            result: "final result",
        };
    })
        .mockImplementationOnce(() => {
        throw new Error("should not be called");
    });
    const start = performance.now();
    const result = await poller(seq, {
        intervalMs: 10,
    });
    const duration = performance.now() - start;
    expect(duration).toBeGreaterThanOrEqual(80);
    expect(result).toEqual({
        state: "success",
        result: "final result",
        stats: {
            attempts: expect.any(Number),
            lastIntervalMs: expect.any(Number),
            totalElapsedMs: expect.any(Number),
        },
    });
});
